def main():
    doc = Document(SOURCE)
    for index, value in CONTENT.items():
        paragraph = doc.paragraphs[index]
        if paragraph.runs:
            paragraph.runs[0].text = value
            for run in paragraph.runs[1:]:
                run.text = ""
        else:
            paragraph.add_run(value)
    doc.add_paragraph("Какие данные получает модель? → Текущий вопрос, выбранные карты и ограниченный контекст только твоей истории. Telegram ID, токены и контактные поля профиля не передаются. Но сведения, которые ты сам написал в заметке или вопросе, могут оказаться в контексте. Не включай туда секреты и контакты.")
    doc.save(OUTPUT)
    print(OUTPUT.name)


if __name__ == "__main__":
    main()
